using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using System.Diagnostics;
class RetryForm:MainForm{public string Root;public int Reads;protected override void OnShown(EventArgs e){}protected override string Folder(){Reads++;string p=Path.Combine(Root,Reads.ToString());Directory.CreateDirectory(p);return p;}}
class Retry311Tests{
 static System.Collections.Generic.IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var x in All(c))yield return x;}}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();var flags=BindingFlags.NonPublic|BindingFlags.Instance;using(var form=new RetryForm{Root=Path.GetFullPath("work/retry311-"+DateTime.Now.Ticks)}){form.Show();Application.DoEvents();System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());var iso=(TextBox)typeof(MainForm).GetField("iso",flags).GetValue(form);iso.Text=Path.GetFullPath("work/test311-bin/MockNoResponse311.exe");bool clicked=false;var timer=new System.Windows.Forms.Timer{Interval=100};timer.Tick+=delegate{var error=Application.OpenForms.Cast<Form>().OfType<ErrorWindow>().FirstOrDefault();if(error==null||clicked)return;iso.Text=Path.GetFullPath("work/test311-bin/MockB.exe");clicked=true;All(error).OfType<Button>().First(b=>b.Text=="Jag har ändrat – försök igen").PerformClick();};timer.Start();var task=(Task)typeof(MainForm).GetMethod("ReadOnlyCore",flags).Invoke(form,new object[]{false});var clock=Stopwatch.StartNew();while(clock.Elapsed.TotalSeconds<20){Application.DoEvents();System.Threading.Thread.Sleep(10);if(clicked&&form.Reads==2&&!(bool)typeof(MainForm).GetField("busy",flags).GetValue(form))break;}timer.Stop();timer.Dispose();task.GetAwaiter().GetResult();if(!clicked||form.Reads!=2||((DataGridView)typeof(MainForm).GetField("grid",flags).GetValue(form)).Rows.Count!=3)throw new Exception("retry must start a new successful read");form.Close();}Console.WriteLine("PASS: real E009 dialog retry closes, releases busy/mutex and starts a successful new read.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
